function current(){const m=room?.meta||{},b=Number(m.battle||1)-1,i=Number(m.index||0)%30;if(m.mode==='math-exam')return MATH_PROPORTIONAL_CLASSWORKS[0].questions[Number(m.index||0)%MATH_PROPORTIONAL_CLASSWORKS[0].questions.length];if(m.mode==='fractions'){const questions=FRACTION_MODULES[b]?.questions||[];return questions[Number(m.index||0)%Math.max(questions.length,1)];}if(m.mode==='reading')return READING_QUIZ[Number(m.index||0)];if(m.mode==='listening')return LISTENING_QUESTIONS[Number(m.index||0)];if(m.mode==='cloze')return CLOZE_BATTLES[b]?.items[i];return (m.subject==='math'?MATH_BATTLES:BATTLES)[b]?.[i];}
function roomQuestionCount(m=room?.meta||{}){return m.mode==='math-exam'?MATH_PROPORTIONAL_CLASSWORKS[0].questions.length:m.mode==='fractions'?(FRACTION_MODULES[Number(m.battle||1)-1]?.questions.length||0):m.mode==='reading'?READING_QUIZ.length:m.mode==='listening'?LISTENING_QUESTIONS.length:m.mode==='cloze'?(CLOZE_BATTLES[Number(m.battle||1)-1]?.items.length||0):30;}
function roomTitle(m=room?.meta||{}){const n=Number(m.battle||1);return m.mode==='math-exam'?'Proportional / Antiproportional · Klassenarbeit 1':m.mode==='fractions'?FRACTION_MODULES[n-1]?.title||'Bruchrechnung':m.mode==='reading'?'Reading · A trip to Cardiff Castle':m.mode==='listening'?'Listening · Activity weekend in Cardiff':m.mode==='cloze'?CLOZE_BATTLES[n-1]?.title||`Lückentext ${n}`:m.subject==='math'?RATIONAL_MATH_TITLES[n-1]||RATIONAL_MATH_TITLES[0]:`Englisch-Battle ${n}`;}
function battleOffset(m=room?.meta||{}){return m.mode==='math-exam'||m.mode==='fractions'||m.mode==='reading'||m.mode==='listening'?0:(Number(m.battle||1)-1)*30;}
function updateBattleChoices(){const subject=document.querySelector('#subject-choice')?.value||'english',select=document.querySelector('#battle-choice');if(!select)return;const opts=subject==='reading'?[['1','Reading · A trip to Cardiff Castle · 13 Fragen']]:subject==='cloze'?[['1','Lückentext 1 · Station 1 · 15 Fragen'],['2','Lückentext 2 · Station 2 · 12 Fragen']]:subject==='listening'?[['1','Listening · Activity weekend in Cardiff · 21 Fragen']]:subject==='math'?[['1',`${RATIONAL_MATH_TITLES[0]} · 30 Fragen`],['2',`${RATIONAL_MATH_TITLES[1]} · 30 Fragen`],['3',`${RATIONAL_MATH_TITLES[2]} · 30 Fragen`]]:[['1','Battle 1 · 30 Fragen'],['2','Battle 2 · 30 Fragen'],['3','Battle 3 · 30 Fragen']];select.innerHTML=opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('');}
