async function cbCreate(){if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}const battle=Number(document.querySelector('#cloze-battle-choice')?.value||1);if(![1,2].includes(battle)){msg('Bitte Station 1 oder 2 auswählen.',true);return;}if(!uid){msg('Verbindung wird hergestellt. Bitte kurz warten.',true);return;}code=String(Math.floor(100000+Math.random()*900000));role='host';slot='';try{await set(ref(db,`rooms/${code}/meta`),{hostUid:uid,stage:'lobby',subject:'english',mode:'cloze',battle,index:(battle-1)*30,createdAt:Date.now()});listen();}catch(e){msg('Lückentext-Raum konnte nicht erstellt werden: '+e.message,true);}}
function countdown(){const m=room?.meta||{};if(m.stage!=='question'&&m.stage!=='reveal')return '';const remaining=Math.max(0,Math.ceil((Number(m.deadline||0)-Date.now())/1000));return m.stage==='question'?`⏱️ Noch ${remaining} Sekunden`:`⏳ Weiter in ${remaining} Sekunden`;}
function render(){if(!room)return;const oldAudio=document.querySelector('#listening-room-audio'),oldAudioTime=oldAudio?.currentTime||0,wasPlaying=!!oldAudio&&!oldAudio.paused;const m=room.meta||{},q=current(),stage=m.stage||'lobby',questionNumber=m.mode==='reading'?Number(m.index||0)+1:Number(m.index||0)%30+1;const stageKey=`${m.battle}:${m.index}:${stage}`;let s=card(`<p class="muted">Raumcode</p><div class="big">${esc(code)}</div><p>${esc(roomTitle(m))} · ${stage==='lobby'?'Warteraum':stage==='question'?`Frage ${questionNumber} von ${roomQuestionCount(m)}`:stage==='reveal'?'Auswertung':'Battle beendet'}</p>${roster()}`);if(m.mode==='reading'&&stage==='lobby')s+=card(readingIntroCard());if(m.mode==='listening')s+=card(`<h3>🎧 Listening-Audio</h3><audio id="listening-room-audio" controls preload="none" style="width:100%"><source src="./rl3_track3.mp3" type="audio/mpeg">Audio kann in diesem Browser nicht abgespielt werden.</audio><p class="muted">Hört euch die Aufnahme an. Danach startet der Schiedsrichter das Battle.</p>`);
if(role==='host'){
 if(stage==='lobby')s+=card(`<h2>Schiedsrichter</h2><p>${esc(roomTitle(m))} starten – ${roomQuestionCount(m)} Fragen mit je 15 Sekunden. Danach erscheint die Rangliste.</p>${btn('▶️ Battle starten','start')}`);
 if(stage==='question'){const a=room.answers?.[m.index]||{};s+=card(`<h2>Frage ${questionNumber} von ${roomQuestionCount(m)}</h2>${m.mode==='reading'?`<p class="muted">${q?.type==='heading'?'Exercise 1 · Match the headings':'Exercise 2 · Right, wrong or not in the text?'}</p>`:''}<p>${esc(q?.q||'')}</p><h2 id="countdown">${countdown()}</h2><p>Antworten: ${Object.keys(a).length} von ${players().length}</p><p class="muted">Automatische Auswertung nach 15 Sekunden</p>`);}
 if(stage==='reveal')s+=card(`<h2>Richtige Antwort</h2><p class="good">${esc(q?.options[q.correct]??'')}</p><h2 id="countdown">${countdown()}</h2>`);
 if(stage==='finished')s+=card(`<h2>🏆 ${esc(roomTitle(m))} beendet!</h2><p>Rangliste nach ${roomQuestionCount(m)} Fragen:</p>${roster()}${m.mode==='reading'?readingTasksHtml():''}${btn('🔄 Neues Spiel','reset')}`);
 s+=card(btn('Zur Startseite','home','alt'));
}else{
 const myAnswer=room.answers?.[m.index]?.[uid];
 if(stage==='lobby')s+=card('<h2>Warteraum</h2><p>Warte, bis der Schiedsrichter das Battle startet.</p>');
 if(stage==='question'&&q){const answered=myAnswer!==undefined;s+=card(`${m.mode==='reading'?`<p class="muted">${q.type==='heading'?'Exercise 1 · Match the headings':'Exercise 2 · Right, wrong or not in the text?'}</p>`:''}<h2>${esc(q.q)}</h2><h2 id="countdown">${countdown()}</h2><div class="answers">${q.options.map((o,i)=>`<button ${answered||Date.now()>=Number(m.deadline||0)?'disabled':''} data-answer="${i}" class="${answered&&Number(myAnswer.choice)===i?'picked':''}">${esc(o)}</button>`).join('')}</div><p class="muted">${answered?'Antwort abgegeben. Warte auf die Auswertung.':'Wähle eine Antwort innerhalb von 15 Sekunden.'}</p>`);}
 if(stage==='reveal')s+=card(`<h2>Auflösung</h2><p>Richtig: <strong class="good">${esc(q?.options[q.correct]??'')}</strong></p><h2 id="countdown">${countdown()}</h2>`);
 if(stage==='finished')s+=card(`<h2>🏆 ${esc(roomTitle(m))} geschafft!</h2><p>Die Rangliste steht oben.</p>${m.mode==='reading'?readingTasksHtml():''}`);
 s+=card(btn('Zur Startseite','home','alt'));
}
app.innerHTML=s;if(m.mode==='listening'&&oldAudio){const nextAudio=document.querySelector('#listening-room-audio');if(nextAudio){nextAudio.currentTime=oldAudioTime;if(wasPlaying)nextAudio.play().catch(()=>{});}}
if(stageKey!==previousStageKey){previousStageKey=stageKey;lastClockText='';}
if(stage==='question'||stage==='reveal'){if(clock===null)clock=setInterval(tick,250);tick();}else stopClock();}
function tick(){if(!room)return;const m=room.meta||{},stage=m.stage;if(stage!=='question'&&stage!=='reveal'){stopClock();return;}const text=countdown();if(text!==lastClockText){const el=document.querySelector('#countdown');if(el)el.textContent=text;lastClockText=text;}if(stage==='question'&&Date.now()>=Number(m.deadline||0)){document.querySelectorAll('[data-answer]').forEach(el=>el.disabled=true);}if(role!=='host'||busy||!m.deadline||Date.now()<Number(m.deadline))return;if(stage==='question')void automaticReveal();else if(stage==='reveal')void automaticNext();}
async function makeRoom(){if(!adminLoggedIn||uid!==ADMIN_UID){msg('Bitte als Schiedsrichter anmelden.',true);return;}const choice=document.querySelector('#subject-choice')?.value||'english';const subject=choice==='math'?'math':'english',mode=choice==='reading'?'reading':choice==='cloze'?'cloze':choice==='listening'?'listening':'vocab';const battle=Number(document.querySelector('#battle-choice')?.value||1);if(!uid){msg('Verbindung wird hergestellt. Bitte kurz warten.',true);return;}code=String(Math.floor(100000+Math.random()*900000));role='host';slot='';try{await set(ref(db,`rooms/${code}/meta`),{hostUid:uid,stage:'lobby',subject,mode,battle,index:battleOffset({mode,battle}),createdAt:Date.now()});listen();}catch(e){msg('Raum konnte nicht erstellt werden: '+e.message,true);}}
function joinForm(){app.innerHTML=card(`<h2>Spiel beitreten</h2><label>Raumcode<input id="roomcode" inputmode="numeric" maxlength="6" placeholder="6-stelliger Code"></label><label>Dein Name<select id="playername">${names.map(n=>`<option>${n}</option>`).join('')}</select></label>${btn('Beitreten','enter')}`)+card(btn('Zurück','home','alt'));}
async function enter(){const c=document.querySelector('#roomcode').value.trim(),name=document.querySelector('#playername').value;if(!uid){msg('Anmeldung läuft. Bitte kurz warten.',true);return;}if(!/^\d{6}$/.test(c)){msg('Bitte sechsstelligen Code eingeben.',true);return;}try{let snap=await get(ref(db,`rooms/${c}`));if(snap.exists()){const r=snap.val();let s=Object.keys(r.slots||{}).find(k=>r.slots[k]?.name===name&&r.slots[k]?.uid===uid);if(!s){if(r.meta?.stage!=='lobby'){msg('Das Battle läuft bereits. Bitte einen neuen Raum im Warteraum öffnen.',true);return;}s=String(names.indexOf(name)+1);if(r.slots?.[s]){msg('Dieser Name ist schon vergeben. Bitte anderen Namen wählen.',true);return;}await set(ref(db,`rooms/${c}/slots/${s}`),{name,uid,score:0});}code=c;role='player';slot=s;listen();return;}snap=await get(ref(db,`grammarRooms/${c}`));if(snap.exists()&&snap.val()?.meta?.kind==='writing'){const r=snap.val();let s=Object.keys(r.slots||{}).find(k=>r.slots[k]?.name===name&&r.slots[k]?.uid===uid);if(!s){if(r.meta?.stage!=='lobby'){msg('Das Writing-Battle läuft bereits. Bitte den nächsten Raum abwarten.',true);return;}s=String(names.indexOf(name)+1);if(r.slots?.[s]){msg('Dieser Name ist schon vergeben. Bitte anderen Namen wählen.',true);return;}await set(ref(db,`grammarRooms/${c}/slots/${s}`),{name,uid,score:0});}wbCode=c;wbRole='player';wbSlot=s;wbListen();return;}msg('Raumcode nicht gefunden. Prüfe die sechs Ziffern.',true);}catch(e){msg('Beitritt fehlgeschlagen: '+e.message,true);}}
async function saveListeningBattleProgress(player,index,correct,runId){if(!player?.uid||!player?.name)return;const progressRef=ref(db,`soloProgress/${player.uid}/${player.name}/listeningUnit2`);try{await runTransaction(progressRef,current=>{const next=current?.runId===runId?{...current}:{runId,done:0,score:0,mistakes:{}};const mistakes={...(next.mistakes||{})};if(!correct)mistakes[index]=(Number(mistakes[index])||0)+1;next.done=Math.min(LISTENING_QUESTIONS.length,(Number(next.done)||0)+1);next.score=(Number(next.score)||0)+(correct?10:0);next.total=LISTENING_QUESTIONS.length;next.finished=next.done>=LISTENING_QUESTIONS.length;next.updatedAt=Date.now();next.timestamp=next.updatedAt;return next;});}catch(e){if(!listeningSyncWarned){listeningSyncWarned=true;msg('Battle läuft weiter; Listening konnte nicht in der Live-Übersicht gespeichert werden: '+e.message,true);}}}
async function automaticReveal(){if(busy||role!=='host'||!room||room.meta?.hostUid!==uid||room.meta.stage!=='question')return;busy=true;const battle=room.meta.battle,index=room.meta.index,mode=room.meta.mode;try{const q=current();if(!q)throw new Error('Frage nicht gefunden');const ans=room.answers?.[index]||{};for(const p of players()){if(ans[p.uid]!==undefined){const correct=Number(ans[p.uid]?.choice)===q.correct;if(correct)await runTransaction(ref(db,`rooms/${code}/slots/${p.id}/score`),x=>(Number(x)||0)+10);if(mode==='listening')await saveListeningBattleProgress(p,index,correct,room.meta.runId||`${code}-${room.meta.createdAt||0}`);}}if(room?.meta?.battle===battle&&room?.meta?.index===index&&room?.meta?.stage==='question')await update(ref(db,`rooms/${code}/meta`),{stage:'reveal',deadline:Date.now()+REVEAL_MS});}catch(e){msg('Automatische Auswertung fehlgeschlagen: '+e.message,true);}finally{busy=false;}}
async function automaticNext(){if(busy||role!=='host'||!room||room.meta?.hostUid!==uid||room.meta.stage!=='reveal')return;busy=true;const m={...room.meta};try{if(Number(m.index)%30>=roomQuestionCount(m)-1)await update(ref(db,`rooms/${code}/meta`),{stage:'finished',deadline:0});else {const nextIndex=Number(m.index)+1;await update(ref(db,`rooms/${code}/meta`),{stage:'question',index:nextIndex,battle:Number(m.battle),deadline:Date.now()+QUESTION_MS});}}catch(e){msg('Nächste Frage konnte nicht gestartet werden: '+e.message,true);}finally{busy=false;}}
async function hostAction(a){if(!adminLoggedIn||uid!==ADMIN_UID){msg('Nur der angemeldete Schiedsrichter darf das.',true);return;}if(role!=='host'||!room||room.meta?.hostUid!==uid){msg('Nur der Schiedsrichter darf das.',true);return;}const m=room.meta;try{if(a==='start'){if(players().length<1){msg('Mindestens ein Spieler muss beitreten.',true);return;}const runId=m.mode==='listening'?`battle-${Date.now()}-${Math.random().toString(36).slice(2,8)}`:m.runId;await update(ref(db,`rooms/${code}/meta`),{stage:'question',index:battleOffset(m),deadline:Date.now()+QUESTION_MS,...(m.mode==='listening'?{runId}:{})});}if(a==='reset'){await remove(ref(db,`rooms/${code}/answers`));for(const p of players())await set(ref(db,`rooms/${code}/slots/${p.id}/score`),0);await update(ref(db,`rooms/${code}/meta`),{stage:'lobby',battle:Number(m.battle),index:battleOffset(m),deadline:0});}}catch(e){msg('Aktion fehlgeschlagen: '+e.message,true);}}
async function answer(i){if(role!=='player'||room?.meta?.stage!=='question'||!uid)return;const n=room.meta.index;if(Date.now()>=Number(room.meta.deadline||0)){msg('Die Antwortzeit ist abgelaufen.',true);return;}if(room.answers?.[n]?.[uid]!==undefined)return;try{await set(ref(db,`rooms/${code}/answers/${n}/${uid}`),{choice:i,at:Date.now()});}catch(e){msg('Antwort konnte nicht gespeichert werden: '+e.message,true);}}

// Solo: 30 reguläre Fragen, danach falsch beantwortete Wörter wiederholen.
// Wiederholungen geben keine zusätzlichen Punkte; alle Zustände bleiben lokal gespeichert.
function cleanMistakes(v){const out={};if(!v||typeof v!=='object')return out;for(const [k,n] of Object.entries(v)){const i=Number(k);if(Number.isInteger(i)&&i>=0&&i<30&&Number.isFinite(Number(n))&&Number(n)>0)out[i]=Math.min(9999,Math.floor(Number(n)));}return out;}
function mistakeRows(b,m){return Object.entries(cleanMistakes(m)).map(([idx,count])=>{const q=BATTLES[b]?.[Number(idx)];if(!q)return null;return {word:q.word||q.q,translation:q.options[q.correct],count,idx:Number(idx)};}).filter(Boolean).sort((a,b)=>b.count-a.count||a.word.localeCompare(b.word,'de'));}
function showMyMistakes(){stopSoloHeartbeat();if(!soloName){soloChooseName();return;}const groups=[0,1,2].map(b=>{const entries=mistakeRows(b,soloSaved(b)?.mistakes);return `<h3>Vokabel-Battle ${b+1}</h3>${entries.length?entries.map(x=>`<div class="player"><strong>${esc(x.word)}</strong> – ${esc(x.translation)}<p class="muted">${x.count}× falsch beantwortet</p></div>`).join(''):'<p class="muted">Noch keine Fehler erfasst.</p>'}`;}).join('');const clozeGroups=CLOZE_BATTLES.map((battle,b)=>{const saved=clozeLoad(b),mistakes=saved?.mistakes||{};const entries=Object.entries(mistakes).filter(([,n])=>Number(n)>0).map(([i,n])=>{const q=battle.items[Number(i)];return q?`<div class="player"><strong>${esc(q.q)}</strong><p>Richtige Lösung: ${esc(q.options[q.correct])} · ${Number(n)}× falsch beantwortet</p></div>`:'';}).join('');return `<h3>${esc(battle.title)}</h3>${entries||'<p class="muted">Noch keine Fehler erfasst.</p>'}`;}).join('');app.innerHTML=card(`<h2>📕 ${esc(soloName)} · Meine Fehlerliste</h2><p>Die Fehler werden bei normalen Fragen und Wiederholungen gezählt. Frühere Battles vor diesem Update sind nicht rückwirkend enthalten.</p>${groups}<h3>✏️ Lückentexte</h3>${clozeGroups}`)+card(btn('Zur Battle-Auswahl','soloHome','alt'));}
function soloKey(b){return `${key}_${soloName}_battle_${b+1}`;}
function soloSave(){if(!solo)return;localStorage.setItem(soloKey(solo.battle),JSON.stringify(solo));touchLearningActivity(soloName,`english_vocab_battle${solo.battle+1}`);void syncSolo();}
function soloSaved(b){try{const s=JSON.parse(localStorage.getItem(soloKey(b))||'null');if(!s||s.battle!==b||!Number.isInteger(s.index)||s.index<0||s.index>30||!Number.isFinite(s.score))return null;
 // Alte Speicherstände vor Einführung des Wiederholungsmodus bleiben kompatibel.
 s.wrong=Array.isArray(s.wrong)?s.wrong.filter(n=>Number.isInteger(n)&&n>=0&&n<30):[];
 s.mistakes=cleanMistakes(s.mistakes);s.review=!!s.review;s.reviewPos=Number.isInteger(s.reviewPos)&&s.reviewPos>=0?s.reviewPos:0;
 if(s.reviewPos>=s.wrong.length)s.reviewPos=0;
 return s;
}catch{return null;}}
async function syncSolo(){if(!uid||!db||!solo||!soloName)return;try{await set(ref(db,`soloProgress/${uid}/${soloName}/battle${solo.battle+1}`),{name:soloName,battle:solo.battle+1,done:solo.index,correct:Math.floor(solo.score/10),score:solo.score,finished:!!solo.finished,mistakes:cleanMistakes(solo.mistakes),updatedAt:Date.now()});}catch(e){msg('Online-Speicherung noch nicht möglich: '+e.message,true);}}
function soloChooseName(){stopSoloHeartbeat();app.innerHTML=card(`<h2>📚 Wer lernt gerade?</h2><p>Wähle deinen Namen, damit der Schiedsrichter deinen Lernfortschritt sehen kann.</p><div class="buttons">${SOLO_NAMES.map((n,i)=>btn(esc(n),`soloName${i}`)).join('')}</div>`)+card(btn('Zurück','home','alt'));}
function soloSetName(i){soloName=SOLO_NAMES[i];localStorage.setItem('vb2solo_name',soloName);soloHome();}
function soloHome(){stopSoloHeartbeat();if(!soloName){soloChooseName();return;}solo=null;const listening=listenLoad(),listenDone=listening?.index||0;app.innerHTML=card(`<h2>📚 ${esc(soloName)} · Englisch lernen</h2><p>Falsche Antworten werden wiederholt. Dein Lernstand wird online und auf diesem Handy gespeichert.</p><h3>Vokabel-Battles</h3>${[0,1,2].map(b=>{const saved=soloSaved(b),done=saved?.index||0;const reviewing=saved&&!saved.finished&&saved.review&&saved.wrong.length;return `<div class="player"><h3>Battle ${b+1}</h3><p>${done} von 30 Fragen erledigt${reviewing?` · 🔁 ${saved.wrong.length} Wörter üben`:''}${saved?.finished?' · abgeschlossen':''}</p><div class="buttons">${btn(saved?'Neu beginnen':'Starten',`soloStart${b}`)}${saved&&!saved.finished?btn('Fortsetzen',`soloResume${b}`,'alt'):''}</div></div>`;}).join('')}<h3>✏️ Lückentexte</h3><p class="muted">Lerne die Lücken aus Station 1 und Station 2. Falsche Antworten kommen zum Üben wieder.</p>${CLOZE_BATTLES.map((battle,b)=>{const saved=clozeLoad(b),total=battle.items.length,done=saved?.index||0;const reviewing=saved&&!saved.finished&&saved.review&&saved.wrong.length;return `<div class="player"><h3>${esc(battle.title)}</h3><p>${esc(battle.subtitle)} · ${done} von ${total} Lücken${reviewing?` · 🔁 ${saved.wrong.length} zum Üben`:''}${saved?.finished?' · abgeschlossen':''}</p><div class="buttons">${btn(saved?'Neu beginnen':'Starten',`clozeStart${b}`)}${saved&&!saved.finished?btn('Fortsetzen',`clozeResume${b}`,'alt'):''}</div></div>`;}).join('')}<h3>🎧 Listening</h3><div class="player"><strong>Activity weekend in Cardiff</strong><p>${listenDone} von ${LISTENING_QUESTIONS.length} Fragen${listening?.finished?' · abgeschlossen':''}</p><div class="buttons">${btn(listening?'Neu beginnen':'Starten','listenStart')}${listening&&!listening.finished?btn('Fortsetzen','listenResume','alt'):''}</div></div><h3>📖 Reading</h3><div class="player"><strong>A trip to Cardiff Castle</strong><p>${readingLoad()?.complete?'abgeschlossen':'Text lesen, verstehen und Aufgaben bearbeiten'}</p>${btn('Reading lernen','readingMenu')}</div><h3>✍️ Writing</h3><div class="player"><strong>Unit 2 · Sports, e-mail und article</strong><p>${WRITING_TASKS.filter(t=>writingLoad().complete?.[t.id]).length} von ${WRITING_TASKS.length} Aufgaben selbst geprüft</p>${btn('Writing lernen','writingMenu')}</div>${btn('📕 Meine Fehlerliste','soloMistakes','alt')}${btn('Anderen Namen wählen','soloChangeName','alt')}`)+card(btn('Zurück','home','alt'));}
function soloStart(b){const previous=soloSaved(b);solo={battle:b,index:0,score:0,finished:false,wrong:[],review:false,reviewPos:0,mistakes:cleanMistakes(previous?.mistakes)};void recordLearningActivity(soloName,`english_vocab_battle${b+1}`);soloSave();soloQuestion();}
function soloResume(b){solo=soloSaved(b);if(!solo){soloStart(b);return;}void recordLearningActivity(soloName,`english_vocab_battle${b+1}`);void syncSolo();if(solo.finished)soloFinished();else soloQuestion();}
function soloQuestion(){if(!solo)return;startSoloHeartbeat();const b=solo.battle;
 if(!solo.review&&solo.index>=30){if(solo.wrong.length){solo.review=true;solo.reviewPos=0;soloSave();}else{soloFinished();return;}}
 if(solo.review&&!solo.wrong.length){soloFinished();return;}
 const i=solo.review?solo.wrong[solo.reviewPos]:solo.index,q=BATTLES[b]?.[i];
 if(!q){msg('Frage konnte nicht geladen werden.',true);return;}
 const title=solo.review?`🔁 Wiederholung · ${solo.wrong.length} Wörter offen`:`Frage ${solo.index+1}/30`;
 app.innerHTML=card(`<h2>${esc(soloName)} · Battle ${b+1}</h2><p>${title} · ${solo.score} Punkte</p><div class="bar"><div class="fill" style="width:${solo.index/30*100}%"></div></div><h2>${esc(q.q)}</h2><div class="answers">${q.options.map((o,j)=>`<button data-soloanswer="${j}">${esc(o)}</button>`).join('')}</div>`)+card(btn('Zur Battle-Auswahl','solo','alt'));
}
function soloAnswer(i){if(!solo||solo.finished)return;const reviewing=solo.review;const questionIndex=reviewing?solo.wrong[solo.reviewPos]:solo.index;
 const q=BATTLES[solo.battle]?.[questionIndex];if(!q||!Number.isInteger(i)||i<0||i>=q.options.length)return;
 // Sofort deaktivieren, damit Doppeltippen keine Fragen überspringt.
 document.querySelectorAll('[data-soloanswer]').forEach(el=>el.disabled=true);
 const ok=i===q.correct;
 if(!ok){solo.mistakes=cleanMistakes(solo.mistakes);solo.mistakes[questionIndex]=(solo.mistakes[questionIndex]||0)+1;}
 if(reviewing){if(ok){solo.wrong.splice(solo.reviewPos,1);if(solo.reviewPos>=solo.wrong.length)solo.reviewPos=0;}
 else if(solo.wrong.length>1)solo.reviewPos=(solo.reviewPos+1)%solo.wrong.length;
 }else{if(ok)solo.score+=10;else if(!solo.wrong.includes(questionIndex))solo.wrong.push(questionIndex);solo.index++;}
 soloSave();
 const remaining=solo.wrong.length;
 app.innerHTML=card(`<h2>${ok?'✅ Richtig!':'❌ Leider falsch'}</h2><p>Richtige Antwort: <strong>${esc(q.options[q.correct])}</strong></p><p>Deine Punkte: ${solo.score} von 300</p>${reviewing?`<p>🔁 Noch ${remaining} ${remaining===1?'Wort':'Wörter'} zum Üben.</p>`:''}${btn('Weiter ➜','soloNext')}`);
}
function soloNext(){if(!solo)return;soloQuestion();}
