let clozeRun=null;
function clozeKey(b){return `vb2solo_${soloName}_cloze_${b+1}`;}
function clozeLoad(b){try{const s=JSON.parse(localStorage.getItem(clozeKey(b))||'null');const total=CLOZE_BATTLES[b]?.items.length||0;if(!s||s.battle!==b||!Number.isInteger(s.index)||s.index<0||s.index>total||!Number.isFinite(s.score))return null;s.wrong=Array.isArray(s.wrong)?s.wrong.filter(n=>Number.isInteger(n)&&n>=0&&n<total):[];s.mistakes=cleanMistakes(s.mistakes);s.review=!!s.review;s.reviewPos=Number.isInteger(s.reviewPos)&&s.reviewPos>=0?s.reviewPos:0;if(s.reviewPos>=s.wrong.length)s.reviewPos=0;return s;}catch{return null;}}
function clozeSave(){if(!clozeRun)return;localStorage.setItem(clozeKey(clozeRun.battle),JSON.stringify(clozeRun));touchLearningActivity(soloName,`english_gap${clozeRun.battle+1}`);void syncClozeProgress();}
async function syncClozeProgress(){if(!db||!uid||!soloName||!clozeRun)return;const battle=CLOZE_BATTLES[clozeRun.battle];if(!battle)return;const now=Date.now();try{await set(ref(db,`soloProgress/${uid}/${soloName}/clozeStation${clozeRun.battle+1}`),{station:clozeRun.battle+1,done:Math.min(battle.items.length,Number(clozeRun.index)||0),total:battle.items.length,score:Number(clozeRun.score)||0,finished:!!clozeRun.finished,mistakes:cleanMistakes(clozeRun.mistakes),updatedAt:now,timestamp:now});clozeSyncWarned=false;}catch(e){if(!clozeSyncWarned){clozeSyncWarned=true;msg('Lückentext bleibt auf diesem Gerät gespeichert; Online-Übersicht konnte nicht aktualisiert werden: '+e.message,true);}}}
function clozeStart(b){const previous=clozeLoad(b);clozeRun={battle:b,index:0,score:0,finished:false,wrong:[],review:false,reviewPos:0,mistakes:cleanMistakes(previous?.mistakes)};void recordLearningActivity(soloName,`english_gap${b+1}`);clozeSave();clozeQuestion();}
function clozeResume(b){clozeRun=clozeLoad(b);if(!clozeRun){clozeStart(b);return;}void recordLearningActivity(soloName,`english_gap${clozeRun.battle+1}`);if(clozeRun.finished)clozeFinished();else clozeQuestion();}
function clozeQuestion(){if(!clozeRun)return;const battle=CLOZE_BATTLES[clozeRun.battle],total=battle.items.length;if(!clozeRun.review&&clozeRun.index>=total){if(clozeRun.wrong.length){clozeRun.review=true;clozeRun.reviewPos=0;clozeSave();}else{clozeFinished();return;}}if(clozeRun.review&&!clozeRun.wrong.length){clozeFinished();return;}const qi=clozeRun.review?clozeRun.wrong[clozeRun.reviewPos]:clozeRun.index,q=battle.items[qi];const title=clozeRun.review?`🔁 Wiederholung · ${clozeRun.wrong.length} noch offen`:`Lücke ${clozeRun.index+1} von ${total}`;app.innerHTML=card(`<h2>${esc(soloName)} · ${esc(battle.title)}</h2><p>${esc(battle.subtitle)}</p><p>${title} · ${clozeRun.score} Punkte</p><div class="bar"><div class="fill" style="width:${clozeRun.index/total*100}%"></div></div><h2>${esc(q.q)}</h2><div class="answers">${q.options.map((o,i)=>`<button data-clozeanswer="${i}">${esc(o)}</button>`).join('')}</div>`)+card(btn('Zur Englisch-Auswahl','soloHome','alt'));}
function clozeAnswer(i){if(!clozeRun||clozeRun.finished)return;const reviewing=clozeRun.review,qi=reviewing?clozeRun.wrong[clozeRun.reviewPos]:clozeRun.index,q=CLOZE_BATTLES[clozeRun.battle].items[qi];if(!q||!Number.isInteger(i)||i<0||i>=q.options.length)return;document.querySelectorAll('[data-clozeanswer]').forEach(el=>el.disabled=true);const ok=i===q.correct;if(!ok){clozeRun.mistakes[qi]=(clozeRun.mistakes[qi]||0)+1;}if(reviewing){if(ok){clozeRun.wrong.splice(clozeRun.reviewPos,1);if(clozeRun.reviewPos>=clozeRun.wrong.length)clozeRun.reviewPos=0;}else if(clozeRun.wrong.length>1)clozeRun.reviewPos=(clozeRun.reviewPos+1)%clozeRun.wrong.length;}else{if(ok)clozeRun.score+=10;else if(!clozeRun.wrong.includes(qi))clozeRun.wrong.push(qi);clozeRun.index++;}clozeSave();app.innerHTML=card(`<h2>${ok?'✅ Richtig!':'❌ Leider falsch'}</h2><p>Richtige Lösung: <strong>${esc(q.options[q.correct])}</strong></p><p>Deine Punkte: ${clozeRun.score} von ${CLOZE_BATTLES[clozeRun.battle].items.length*10}</p>${reviewing?`<p>🔁 Noch ${clozeRun.wrong.length} Lücken zum Üben.</p>`:''}${btn('Weiter ➜','clozeNext')}`);}
function clozeNext(){if(clozeRun)clozeQuestion();}
function clozeFinished(){if(!clozeRun)return;clozeRun.finished=true;clozeRun.index=CLOZE_BATTLES[clozeRun.battle].items.length;clozeRun.wrong=[];clozeRun.review=false;clozeRun.reviewPos=0;clozeSave();const battle=CLOZE_BATTLES[clozeRun.battle];app.innerHTML=card(`<h2>🏆 ${esc(battle.title)} geschafft!</h2><p>Alle Lücken wurden richtig geübt.</p><p class="score">${clozeRun.score} von ${battle.items.length*10} Punkten</p>${btn('Lückentext wiederholen',`clozeStart${clozeRun.battle}`)}`)+card(btn('Zur Englisch-Auswahl','soloHome','alt'));}
let listeningRun=null,listeningSyncWarned=false;
const readingKey=()=>`vb2reading_${soloName}_cardiff`;
function readingLoad(){try{return JSON.parse(localStorage.getItem(readingKey())||'null');}catch{return null;}}
function readingSave(){if(readingRun){localStorage.setItem(readingKey(),JSON.stringify(readingRun));void syncReadingProgress();}}
async function syncReadingProgress(){if(!db||!uid||!soloName||!readingRun)return;const now=Date.now();try{await set(ref(db,`soloProgress/${uid}/${soloName}/readingCardiff`),{done:Math.min(READING_QUIZ.length,Number(readingRun.index)||0),total:READING_QUIZ.length,score:Number(readingRun.score)||0,writingDone:Math.min(READING_TEXT_TASKS.length,Number(readingRun.textIndex)||0),writingTotal:READING_TEXT_TASKS.length,finished:!!readingRun.complete,updatedAt:now,timestamp:now});readingSyncWarned=false;}catch(e){if(!readingSyncWarned){readingSyncWarned=true;msg('Reading bleibt auf diesem Gerät gespeichert; die Live-Übersicht konnte nicht aktualisiert werden: '+e.message,true);}}}
function readingMenu(){if(!soloName){soloChooseName();return;}readingRun=null;const saved=readingLoad();app.innerHTML=card(`<h2>📖 Reading · A trip to Cardiff Castle</h2><p>Lies den Text auf Englisch und Deutsch. Danach kommen dieselben Aufgaben wie auf dem Arbeitsblatt: Überschriften zuordnen, Aussagen ankreuzen und zum Schluss schreiben.</p><p>${saved?.complete?'Zuletzt abgeschlossen · ':''}${saved?`${saved.score||0} von ${READING_QUIZ.length*10} Punkten`:'Noch nicht begonnen'}</p>${btn('Lesen und üben','readingIntro')}`)+card(btn('Zur Englisch-Auswahl','soloHome','alt'));}
function readingIntro(){readingLanguage='en';readingIntroRender();}
function readingIntroRender(){const text=readingLanguage==='de'?READING_TEXT_DE:READING_TEXT_EN;app.innerHTML=card(`<h2>📖 A trip to Cardiff Castle</h2><p>Lies den Text einmal auf Englisch und einmal auf Deutsch.</p><div class="buttons">${btn('🇬🇧 English','readingLangEn',readingLanguage==='en'?'':'alt')}${btn('🇩🇪 Deutsch','readingLangDe',readingLanguage==='de'?'':'alt')}</div>${READING_ILLUSTRATION}<div style="line-height:1.7">${readingParagraphs(text)}</div>${btn('Weiter zu den Aufgaben','readingStart')}`)+card(btn('Zur Reading-Auswahl','readingMenu','alt'));}
function readingStart(){readingRun={index:0,score:0,textIndex:0,textAnswers:[],complete:false,checked:false};void recordLearningActivity(soloName,'english_reading');readingSave();readingQuestion();}
function readingQuestion(){if(!readingRun)return;if(readingRun.index>=READING_QUIZ.length){readingTextTask();return;}const q=READING_QUIZ[readingRun.index],heading=q.type==='heading',num=readingRun.index+1,taskLabel=heading?'Aufgabe 1 · Match the headings':'Aufgabe 2 · Right, wrong or not in the text?';app.innerHTML=card(`<h2>📖 ${esc(soloName)} · Reading</h2><p>${taskLabel} · ${num} von ${READING_QUIZ.length} · ${readingRun.score} Punkte</p><h3>${esc(q.q)}</h3><p class="muted">${heading?'Ordne die Überschrift dem passenden Absatz zu. Ein Vorschlag bleibt übrig.':'Kreuze an: right, wrong oder not in the text.'}</p><div class="answers">${q.options.map((o,i)=>`<button data-readinganswer="${i}">${esc(o)}</button>`).join('')}</div>`)+card(btn('Zur Reading-Auswahl','readingMenu','alt'));}
function readingAnswer(i){if(!readingRun||readingRun.complete)return;const q=READING_QUIZ[readingRun.index];if(!q||!Number.isInteger(i)||i<0||i>=q.options.length)return;document.querySelectorAll('[data-readinganswer]').forEach(el=>el.disabled=true);const ok=i===q.correct;if(ok)readingRun.score+=10;readingRun.index++;readingRun.checked=false;readingSave();app.innerHTML=card(`<h2>${ok?'✅ Richtig!':'❌ Nicht ganz'}</h2><p>Richtige Antwort: <strong>${esc(q.options[q.correct])}</strong></p><p>${readingRun.score} Punkte</p>${btn('Weiter ➜','readingNext')}`);}
function readingTextTask(){if(!readingRun)return;const i=readingRun.textIndex;if(i>=READING_TEXT_TASKS.length){readingFinish();return;}const task=READING_TEXT_TASKS[i],saved=String(readingRun.textAnswers[i]||'');app.innerHTML=card(`<h2>✍️ Reading · Schreibaufgabe ${i+1} von ${READING_TEXT_TASKS.length}</h2><p>${esc(task.q)}</p><textarea data-readingtext rows="5" maxlength="1200" placeholder="Schreibe deine Antwort hier …" style="width:100%;padding:12px;border-radius:10px;font:inherit">${esc(saved)}</textarea>${readingRun.checked?`<div class="player"><strong>Musterlösung</strong><p style="white-space:pre-wrap">${esc(task.sample)}</p><p class="muted">Vergleiche deine Antwort mit den wichtigen Informationen.</p></div>${btn(i+1<READING_TEXT_TASKS.length?'Nächste Textaufgabe':'Reading beenden','readingTextNext')}`:btn('Antwort speichern und Musterlösung ansehen','readingTextCheck')}`)+card(btn('Zur Reading-Auswahl','readingMenu','alt'));}
function readingTextCheck(){const field=document.querySelector('[data-readingtext]');if(!readingRun||!field)return;readingRun.textAnswers[readingRun.textIndex]=field.value.trim();readingRun.checked=true;readingSave();readingTextTask();}
function readingTextNext(){if(!readingRun)return;readingRun.textIndex++;readingRun.checked=false;readingSave();readingTextTask();}

