function listenFinish(){if(!listeningRun)return;listeningRun.finished=true;listeningRun.index=LISTENING_QUESTIONS.length;listenSave();app.innerHTML=card(`<h2>🏆 Listening geschafft!</h2><p>Activity weekend in Cardiff</p><p class="score">${listeningRun.score} von ${LISTENING_QUESTIONS.length*10} Punkten</p>${btn('Listening wiederholen','listenStart')}`)+card(btn('Zur Englisch-Auswahl','soloHome','alt'));}
function listenNext(){listenQuestion();}
function latestNamedProgress(entries,name,key){let latest=null;for(const perDevice of Object.values(entries||{})){const record=perDevice?.[name]?.[key];if(record&&typeof record==='object'&&Number(record.updatedAt||record.timestamp||0)>Number(latest?.updatedAt||latest?.timestamp||0))latest=record;}return latest;}
function activitySnapshot(activityData,name,id,dayKey,weekKey){let today=0,week=0,lastAt=0;for(const device of Object.values(activityData||{})){const item=device?.[name]?.[id];if(!item)continue;if(item.dayKey===dayKey)today+=Number(item.dayCount)||0;if(item.weekKey===weekKey)week+=Number(item.weekCount)||0;lastAt=Math.max(lastAt,Number(item.lastAt)||0);}return {today,week,lastAt};}
function activityDateKeys(timestamp=Date.now()){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(timestamp)).map(x=>[x.type,x.value]));const date=new Date(Date.UTC(Number(p.year),Number(p.month)-1,Number(p.day))),day=date.getUTCDay()||7;date.setUTCDate(date.getUTCDate()+4-day);const isoYear=date.getUTCFullYear(),yearStart=new Date(Date.UTC(isoYear,0,1)),week=Math.ceil((((date-yearStart)/86400000)+1)/7);return {dayKey:`${p.year}-${p.month}-${p.day}`,weekKey:`${isoYear}-W${String(week).padStart(2,'0')}`};}
function activityCounts(activityData,name,ids){const {dayKey,weekKey}=activityDateKeys();let today=0,week=0;for(const id of ids){const c=activitySnapshot(activityData,name,id,dayKey,weekKey);today+=c.today;week+=c.week;}return `<small class="activity-inline">Heute ${today}× · Woche ${week}×</small>`;}
function activityBreakdown(activityData,name,items){const {dayKey,weekKey}=activityDateKeys();return `<small class="activity-inline">${items.map(({id,title})=>{const c=activitySnapshot(activityData,name,id,dayKey,weekKey);return `${esc(title)}: heute ${c.today}× · Woche ${c.week}×`;}).join('<br>')}</small>`;}
function livePanel(title,content,key,accent){return `<details class="card live-panel fraction-topic" data-live-key="${key}" style="--live-accent:${accent};--fraction-accent:${accent}"><summary><span class="fraction-title">${title}</span></summary><div class="live-panel-content fraction-children">${content}</div></details>`;}
function errorEvaluationPanel(subject,period,activityData,names){const {dayKey,weekKey}=activityDateKeys(),label=period==='day'?'Heute':'Diese Woche';const content=names.map(name=>{const found=new Map();for(const device of Object.values(activityData||{}))for(const [exercise,entry] of Object.entries(device?.[name]||{}))for(const [index,item] of Object.entries(entry?.errorItems||{})){if(item?.subject!==subject)continue;const matches=period==='day'?item.dayKey===dayKey:item.weekKey===weekKey;if(!matches&&!item.resolved){}else if(!matches)continue;const key=`${exercise}:${index}`,old=found.get(key);if(!old||Number(item.lastWrongAt||0)>Number(old.item.lastWrongAt||0))found.set(key,{exercise,index,item});}const topics=new Map();for(const row of found.values()){const title=String(row.item.topic||row.exercise);if(!topics.has(title))topics.set(title,[]);topics.get(title).push(row);}if(!topics.size)return `<div class="player"><strong>${esc(name)}</strong><p class="muted">${label}: noch keine Fehler erfasst. Neue Fehler erscheinen hier automatisch.</p></div>`;return `<div class="player"><h3>${esc(name)}</h3>${[...topics.entries()].map(([title,rows])=>{const open=rows.filter(x=>!x.item.resolved).length,done=rows.length-open;return `<details class="fraction-errors"><summary>${esc(title)} · ${open} offen · ${done} richtig bearbeitet</summary>${rows.map(({item})=>`<div class="fraction-error-item"><strong>${esc(item.prompt||'Aufgabe')}</strong><p>${item.options?`Richtige Antwort: ${esc(item.options[item.correctIndex]??'')}`:`Richtige Lösung: ${esc((item.accepted||[]).join(' / '))}`}</p>${subject==='math'&&item.explanation?`<p class="muted" style="white-space:pre-line">Rechenweg: ${esc(item.explanation)}</p>`:''}<p class="${item.resolved?'good':'error'}">${item.resolved?'✅ Richtig bearbeitet':'❌ Noch offen'} · ${Number(item.count)||1}× falsch</p></div>`).join('')}</details>`;}).join('')}</div>`;}).join('');return livePanel(`📊 ${subject==='math'?'Mathe':'Englisch'} · ${period==='day'?'Tägliche':'Wöchentliche'} Fehlerauswertung`,content,`live-errors-${subject}-${period}`,period==='day'?'#ffd166':'#c4b5fd');}
function progressRows(entries,key,totalForStation,names=SOLO_NAMES,activityData={}){return [0,1].map(i=>{const total=totalForStation(i),station=i+1,ids=key==='grammarStation'?GRAMMAR[i].tasks.map((_,ti)=>`english_grammar_${station}_task${ti+1}`):[`english_gap${station}`];return `<h3>Station ${station}</h3>${names.map(name=>{const v=latestNamedProgress(entries,name,`${key}${station}`);return `<div class="player row"><strong>${esc(name)}</strong><span>${v?`${Math.min(total,Number(v.done)||0)}/${total} · ${Number(v.score)||0} Punkte`:'Noch keine Online-Daten'} ${key==='grammarStation'?activityBreakdown(activityData,name,ids.map((id,ti)=>({id,title:GRAMMAR[i].tasks[ti].title}))):activityCounts(activityData,name,ids)}</span></div>`;}).join('')}`;}).join('');}
