  const rows=visibleNames.map(name=>{const records=battleNumbers.map(b=>latest[name+':battle'+b]);const recent=records.some(v=>v&&now-Number(v.updatedAt||0)<90000);const cells=records.map((v,i)=>{const battle=battleNumbers[i],total=totalFor(battle),activityId=isMath?(battle===4?'math_rational_cards':`math_rational_battle${battle}`):`english_vocab_battle${battle}`,progress=v?`${Math.min(total,Number(v.done)||0)}/${total} · ${Number(v.score)||0} P`:'–';return `${progress}${activityCounts(activityData,name,[activityId])}`;});const done=records.reduce((n,v,i)=>n+Math.min(totalFor(battleNumbers[i]),Number(v?.done)||0),0),points=records.reduce((n,v)=>n+(Number(v?.score)||0),0);return `<tr><th style="padding:10px 6px">${esc(name)} ${recent?'🟢':'⚪'}</th>${cells.map(x=>`<td>${x}</td>`).join('')}<td><strong>${done}/${totalPossible}</strong><br>${points} P</td></tr>`;}).join('');
