  const details=visibleNames.map(name=>{const records=battleNumbers.map(b=>latest[name+':battle'+b]);const content=records.map((v,index)=>{const battle=battleNumbers[index],total=totalFor(battle),label=isMath&&battle===4?'Battle 4 · Übung 4':'Battle '+battle;const summary=`<p><strong>${label}:</strong> ${v?`${Math.min(total,Number(v.done)||0)}/${total} · ${Number(v.score)||0} Punkte`:'Noch keine Online-Daten'}</p>`;let mistakes='';if(isMath&&battle===4){mistakes=Object.entries(v?.mistakes||{}).map(([i,count])=>`<div class="player">Karte ${Number(i)+1} · ${Number(count)||0}× zum Wiederholen markiert</div>`).join('');}else if(isMath){mistakes=Object.entries(v?.mistakes||{}).map(([i,count])=>{const q=MATH_BATTLES[battle-1]?.[Number(i)];return q?`<div class="player">${esc(q.q)} → <strong>${esc(q.options[q.correct])}</strong> · ${Number(count)||0}× falsch</div>`:'';}).join('');}else{mistakes=mistakeRows(battle-1,v?.mistakes).map(x=>`<div class="player">${esc(x.word)} – ${esc(x.translation)} · ${x.count}× falsch</div>`).join('');}return `<p><strong>${label} · Fehlerliste</strong></p>`+(mistakes||'<p class="muted">Keine Fehler online erfasst.</p>');}).join('');return `<details class="player" data-live-key="progress-${isMath?'math':'english'}-${name}"><summary><strong>${esc(name)}</strong> · Ergebnisse und Fehlerliste</summary>${content}</details>`;}).join('');
