 const proportionalClassworkProgress=MATH_PROPORTIONAL_CLASSWORKS.map((exam,index)=>{const battleNumber=8+index,records=visibleNames.map(name=>{const p=latestNamedProgress(mathEntries,name,'battle'+battleNumber),done=p?Math.min(exam.questions.length,Number(p.done)||0):0,errors=Object.entries(p?.mistakes||{}).filter(([,count])=>Number(count)>0),errorCount=errors.reduce((n,[,count])=>n+Number(count||0),0),details=errors.length?'<details class="fraction-errors"><summary>Fehler ansehen · '+errorCount+'</summary>'+errors.map(([i,count])=>{const q=exam.questions[Number(i)];return q?'<div class="fraction-error-item"><strong>'+esc(q.q)+'</strong><p><strong>Richtige Lösung:</strong> '+esc(q.options[q.correct])+'</p><p>'+esc(q.explanation)+' · '+Number(count)+'× falsch</p></div>':'';}).join('')+'</details>':'<p class="muted small">Keine Fehler erfasst.</p>';return '<div class="player"><div class="row"><strong>'+esc(name)+' '+(p&&Date.now()-Number(p.updatedAt||0)<90000?'🟢':'⚪')+'</strong><span>'+ (p?done+'/'+exam.questions.length+' Aufgaben · '+(Number(p.score)||0)+'/'+exam.points+' Punkte'+(p.finished?' · fertig':''):'Noch keine Online-Daten')+' '+activityCounts(activityData,name,[`math_proportional_exam${index+1}`])+'</span></div>'+details+'</div>';}).join('');return livePanel('📝 '+exam.title,'<p class="muted">Empfohlene Arbeitszeit: 45 Minuten · 15 Aufgaben · 30 Punkte</p>'+records,'live-math-proportional-exam-'+(index+1),['#ffd166','#fda4af','#c4b5fd'][index]);}).join('');
