async function resetLearning(subject){
 if(resetBusy||!adminLoggedIn||uid!==ADMIN_UID){msg('Nur der Schiedsrichter darf Lernstände löschen.',true);return;}
 if(!['english','math'].includes(subject)){msg('Bitte ein Fach auswählen.',true);return;}
 const target=document.querySelector(`#reset-target-${subject}`)?.value;
 const moduleId=document.querySelector(`#reset-box-${subject}`)?.value;
 if(target!=='all'&&!SOLO_NAMES.includes(target)){msg('Bitte ein Kind auswählen.',true);return;}
 const selected=moduleId==='all'?null:(LEARNING_RESET_MODULES[subject]||[]).find(x=>x[0]===moduleId);
 if(moduleId!=='all'&&!selected){msg('Bitte ein Lernkästchen auswählen.',true);return;}
 const label=target==='all'?'ALLE VIER KINDER':target;
 const subjectLabel=subject==='math'?'Mathe':'Englisch';
 const moduleLabel=selected?selected[1]:`alle ${subjectLabel}-Lernkästchen`;
 if(!window.confirm(`ACHTUNG: ${moduleLabel} für ${label} zurücksetzen? Die übrigen Lernkästchen bleiben erhalten.`))return;
 if(!window.confirm(`Endgültig ${moduleLabel} für ${label} löschen?`))return;
 resetBusy=true;
 try{
  const targets=target==='all'?SOLO_NAMES:[target];
  const progressPath=subject==='math'?'mathProgress':'soloProgress';
  const resetPath=subject==='math'?'learningResetsMath':'learningResetsEnglish';
  const stamp=Date.now();
  for(const name of targets){await set(ref(db,selected?resetPath+'/'+name+'__'+moduleId:resetPath+'/'+name),stamp);if(subject==='math'&&selected&&selected[0].startsWith('fraction_'))await set(ref(db,'learningResets/'+name+'__math_'+moduleId),stamp);if(subject==='math'&&selected&&selected[0]==='battle6')await set(ref(db,'learningResets/'+name+'__math_battle6'),stamp);if(subject==='math'&&selected&&selected[0]==='proportional')await set(ref(db,'learningResets/'+name+'__math_proportional'),stamp);if(subject==='math'&&selected&&(selected[0].startsWith('proportional_exam')||selected[0].startsWith('proportional_practice_')))await set(ref(db,'learningResets/'+name+'__math_'+moduleId),stamp);}
  const snap=await get(ref(db,progressPath));
  const paths={};
  for(const [device,perDevice] of Object.entries(snap.val()||{})){
   for(const name of targets){
    const records=perDevice?.[name];if(!records)continue;
    const keys=selected?selected[2]:Object.keys(records);
    for(const key of keys)if(Object.prototype.hasOwnProperty.call(records,key))paths[`${device}/${name}/${key}`]=null;
   }
  }
  if(Object.keys(paths).length)await update(ref(db,progressPath),paths);
  msg(`${moduleLabel} für ${label} zurückgesetzt. Die übrigen Lernkästchen bleiben erhalten.`);
 }catch(e){msg('Rücksetzen nicht vollständig abgeschlossen: '+e.message,true);}
 finally{resetBusy=false;}
}
function showDashboard(){
 if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}
 stopDashboard();stopSoloHeartbeat();
 app.innerHTML=card('<h2>📊 Live-Lernübersicht</h2><p>Online-Lernstände werden geladen …</p>')+card(btn('Zurück','home','alt'));
 if(!uid){msg('Bitte kurz warten, bis die Anmeldung abgeschlossen ist.',true);return;}
 let englishData={},mathData={},activityData={};const refresh=()=>{liveDashboardData={english:englishData,math:mathData,activity:activityData};renderDashboard(englishData,mathData,activityData);};const offEnglish=onValue(ref(db,'soloProgress'),snap=>{englishData=snap.val()||{};refresh();},e=>msg('Englisch konnte nicht geladen werden: '+e.message,true));const offMath=onValue(ref(db,'mathProgress'),snap=>{mathData=snap.val()||{};refresh();},e=>msg('Mathe konnte nicht geladen werden: '+e.message+'. Bitte Firebase-Regeln für mathProgress prüfen.',true));const offActivity=onValue(ref(db,'learningActivity'),snap=>{activityData=snap.val()||{};refresh();},e=>msg('Häufigkeitsübersicht konnte nicht geladen werden. Bitte Firebase-Regeln für learningActivity prüfen.',true));dashboardUnsubscribe=()=>{offEnglish();offMath();offActivity();};
}

// === Mathe Klasse 7 NRW: rationale Zahlen ===
let mathName='',mathRun=null,mathView='';
const mathKey=(n,b)=>`vb2math_${n}_battle_${b+1}`;
function mathLoad(n,b){try{return JSON.parse(localStorage.getItem(mathKey(n,b))||'null');}catch{return null;}}
function mathSave(){if(!mathRun)return;mathRun.updatedAt=Date.now();localStorage.setItem(mathKey(mathName,mathRun.b),JSON.stringify(mathRun));touchLearningActivity(mathName,mathActivityId(mathRun.b));void mathSync();}
async function mathSync(){if(!db||!uid||!mathRun||!mathName)return;try{const stamp=Math.max(Number(resetState?.all)||0,Number(resetState?.[mathName])||0);if(mathRun.updatedAt<=stamp)return;await set(ref(db,`mathProgress/${uid}/${mathName}/battle${mathRun.b+1}`),{done:mathRun.index,score:mathRun.score,mistakes:mathRun.mistakes,updatedAt:mathRun.updatedAt,finished:mathRun.finished});}catch(e){msg('Mathe online noch nicht verfügbar – der Fortschritt bleibt auf diesem Gerät gespeichert.',true);}}
function mathChoose(){mathRun=null;app.innerHTML=card('<h2>🔢 Mathe · Klasse 7 NRW</h2><p>Rationale Zahlen – wer lernt?</p>'+SOLO_NAMES.map((n,i)=>btn(esc(n),`mathName${i}`)).join(''))+card(btn('Zur Fächerauswahl','home','alt'));}
function mathSetName(i){mathName=SOLO_NAMES[i];mathHome();}
function mathHome(){mathRun=null;const titles=['Zahlen vergleichen, addieren und subtrahieren','Multiplizieren und dividieren','Klammern und gemischte Rechnungen'];app.innerHTML=card(`<h2>🔢 Mathe · ${esc(mathName)}</h2><p>Klasse 7 · Rationale Zahlen</p>`+titles.map((t,b)=>{const s=mathLoad(mathName,b);return `<div class="player"><h3>${RATIONAL_MATH_TITLES[b]}</h3><p>${esc(t)}</p><p>${s?.index||0}/30 Aufgaben · ${s?.score||0} Punkte</p>${btn('Neu beginnen',`mathStart${b}`)}${s&&!s.finished?btn('Fortsetzen',`mathResume${b}`,'alt'):''}</div>`;}).join('')+btn('📕 Meine Mathe-Fehlerliste','mathMistakes','alt'))+card(btn('Fach wechseln','home','alt'));}
function mathStart(b,resume=false){const s=resume?mathLoad(mathName,b):null;mathRun=s&&s.index>=0?s:{b,index:0,score:0,finished:false,mistakes:{}};void recordLearningActivity(mathName,mathActivityId(b));mathSave();mathQuestion();}
function mathQuestion(){if(!mathRun)return;if(mathRun.index>=30){mathRun.finished=true;mathSave();app.innerHTML=card(`<h2>🏆 ${RATIONAL_MATH_TITLES[mathRun.b]} geschafft!</h2><p>${mathRun.score} von 300 Punkten</p>`+btn('Zur Übersicht','mathHome'));return;}const q=MATH_BATTLES[mathRun.b][mathRun.index];app.innerHTML=card(`<h2>🔢 ${RATIONAL_MATH_TITLES[mathRun.b]}</h2><p>Aufgabe ${mathRun.index+1}/30 · ${mathRun.score} Punkte</p><h2>${esc(q.q)}</h2><div class="answers">${q.options.map((o,i)=>`<button data-mathanswer="${i}">${esc(o)}</button>`).join('')}</div>`)+card(btn('Zur Mathe-Übersicht','mathHome','alt'));}
function mathAnswer(i){if(!mathRun||mathRun.index>=30)return;const q=MATH_BATTLES[mathRun.b][mathRun.index],ok=i===q.correct;document.querySelectorAll('[data-mathanswer]').forEach(el=>el.disabled=true);if(ok)mathRun.score+=10;else mathRun.mistakes[mathRun.index]=(mathRun.mistakes[mathRun.index]||0)+1;mathRun.index++;mathSave();app.innerHTML=card(`<h2>${ok?'✅ Richtig!':'❌ Leider falsch'}</h2><p>Richtige Lösung: <strong>${esc(q.options[q.correct])}</strong></p><p>${mathRun.score} Punkte</p>`+btn('Weiter ➜','mathNext'));}
function mathMistakes(){const content=[0,1,2].map(b=>{const s=mathLoad(mathName,b),m=s?.mistakes||{};return `<h3>${RATIONAL_MATH_TITLES[b]}</h3>`+(Object.keys(m).length?Object.entries(m).map(([i,c])=>`<p>${esc(MATH_BATTLES[b][Number(i)].q)} → <strong>${esc(MATH_BATTLES[b][Number(i)].options[MATH_BATTLES[b][Number(i)].correct])}</strong> · ${c}× falsch</p>`).join(''):'<p>Noch keine Fehler.</p>');}).join('');app.innerHTML=card(`<h2>📕 ${esc(mathName)} · Mathe-Fehlerliste</h2>${content}`)+card(btn('Zur Mathe-Übersicht','mathHome','alt'));}
function mathAction(v){if(v==='mathChoose')mathChoose();else if(v==='mathHome')mathHome();else if(v==='mathMistakes')mathMistakes();else if(v==='mathNext')mathQuestion();else if(/^mathName[0-3]$/.test(v))mathSetName(Number(v.slice(-1)));else if(/^mathStart[012]$/.test(v))mathStart(Number(v.slice(-1)));else if(/^mathResume[012]$/.test(v))mathStart(Number(v.slice(-1)),true);else return false;return true;}


// Grammatik-Battle: Originalaufgaben, Texteingaben und Bewertung durch den Schiedsrichter.
const GB_TIME=45000;
let gbCode='',gbRoom=null,gbOff=null,gbBusy=false,gbTimer=null;
const gbNorm=s=>String(s||'').trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\s+/g,' ');
const gbQuestions=st=>GRAMMAR[st].tasks.flatMap((t,ti)=> (t.items||t.open||[]).map((item,i)=>({task:ti,number:i+1,title:t.title,intro:t.intro||'',prompt:t.items?item[0]+' _____ '+item[1]:(t.prompts?.[i]||'Schreibe einen vollständigen englischen Satz.'),accepted:t.items?item[2]:null,example:t.open?.[i]||null})));
function gbStop(){if(gbOff){gbOff();gbOff=null;}if(gbTimer){clearInterval(gbTimer);gbTimer=null;}gbRoom=null;gbCode='';}
function gbListen(){if(gbOff)gbOff();gbOff=onValue(ref(db,`grammarRooms/${gbCode}`),s=>{gbRoom=s.val();if(!gbRoom){msg('Grammatik-Raum nicht gefunden.',true);return;}gbRender();},e=>msg('Grammatik-Battle: '+e.message,true));}
function gbPlayers(){return Object.entries(gbRoom?.slots||{}).map(([id,v])=>({id,...v})).sort((a,b)=>(b.score||0)-(a.score||0));}
function gbRanking(){return gbPlayers().map((p,i)=>`<div class="player row"><span>${i+1}. ${esc(p.name)}</span><strong>${p.score||0} P</strong></div>`).join('')||'<p>Warte auf Spieler.</p>';}
function gbClock(){if(!gbRoom||gbRoom.meta?.stage!=='question')return;const el=document.querySelector('#gb-clock');if(el)el.textContent='⏱️ '+Math.max(0,Math.ceil((Number(gbRoom.meta.deadline||0)-Date.now())/1000))+' Sekunden';}

function gbChoose(){if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}app.innerHTML=card('<h2>🏆 Grammatik-Battle</h2><p>Die Kinder tippen die Originalantworten selbst ein. Du bewertest jede Antwort und startest die nächste Frage.</p><label>Station<select id="gb-station"><option value="0">Station 1</option><option value="1">Station 2</option></select></label>'+btn('Raum erstellen','gbCreate'))+card(btn('Zurück','home','alt'));}
async function gbCreate(){const station=Number(document.querySelector('#gb-station')?.value||0);gbStop();gbCode=String(Math.floor(100000+Math.random()*900000));try{await set(ref(db,`grammarRooms/${gbCode}/meta`),{hostUid:uid,station,index:0,stage:'lobby',deadline:0,createdAt:Date.now()});gbListen();}catch(e){msg('Raum erstellen: '+e.message,true);}}
function gbRender(){const m=gbRoom.meta||{},qs=gbQuestions(Number(m.station||0)),q=qs[Number(m.index||0)],stage=m.stage;let out=card(`<h2>🏆 Grammatik · Station ${Number(m.station)+1}</h2><p>Raumcode</p><div class="big">${esc(gbCode)}</div><p>${stage==='finished'?'Beendet':`Aufgabe ${Math.min(qs.length,Number(m.index)+1)} von ${qs.length}`}</p>${gbRanking()}`);
if(stage==='lobby')out+=card('<h3>Warteraum</h3><p>Die Kinder treten mit dem Raumcode bei.</p>'+btn('▶️ Battle starten','gbStart'));
if(stage==='question'&&q){const submissions=gbRoom.submissions?.[m.index]||{},reviews=gbRoom.reviews?.[m.index]||{};out+=card(`<h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><p id="gb-clock"></p><p><strong>Musterlösung:</strong> ${esc(q.accepted?.join(' / ')||q.example||'')}</p><p class="muted">Jede Antwort einzeln bewerten. Bei freien Sätzen sind andere richtige Formulierungen möglich.</p>`+gbPlayers().map(p=>{const ans=submissions[p.uid];const r=reviews[p.uid];return `<div class="player"><strong>${esc(p.name)}</strong><p>${ans?esc(ans.text):'Noch keine Antwort'}</p>${r?`<p>${r.correct?'✅ Richtig':'❌ Falsch'} – bewertet</p>`:ans?`${btn('✅ Richtig',`gbYes_${p.uid}`)} ${btn('❌ Falsch',`gbNo_${p.uid}`,'alt')}`:''}</div>`;}).join('')+btn('Nächste Aufgabe ➜','gbNext'));
if(stage==='finished')out+=card('<h2>🏆 Endstand</h2>'+gbRanking()+btn('Neues Spiel','gbRestart'));
app.innerHTML=out+card(btn('Zur Startseite','home','alt'));if(gbTimer)clearInterval(gbTimer);if(stage==='question'){gbTimer=setInterval(gbClock,1000);gbClock();}}
}
async function saveGrammarProgress(player,station,index,correct,runId,total){if(!player?.uid||!player?.name)return;const progressRef=ref(db,`soloProgress/${player.uid}/${player.name}/grammarStation${station+1}`);await runTransaction(progressRef,current=>{const next=current?.runId===runId?{...current}:{runId,done:0,score:0,correct:0,mistakes:{}};const mistakes={...(next.mistakes||{})};if(!correct)mistakes[index]=(Number(mistakes[index])||0)+1;next.done=Math.min(total,(Number(next.done)||0)+1);next.score=(Number(next.score)||0)+(correct?10:0);next.correct=(Number(next.correct)||0)+(correct?1:0);next.total=total;next.station=station+1;next.mistakes=mistakes;next.finished=next.done>=total;next.updatedAt=Date.now();next.timestamp=next.updatedAt;return next;});}
async function gbHost(action){if(!adminLoggedIn||uid!==ADMIN_UID||gbRoom?.meta?.hostUid!==uid||gbBusy)return;gbBusy=true;try{const m=gbRoom.meta,qs=gbQuestions(Number(m.station));if(action==='gbStart'){if(!gbPlayers().length){msg('Mindestens ein Spieler muss beitreten.',true);return;}const runId=`${Date.now()}-${Math.random().toString(36).slice(2,8)}`;await update(ref(db,`grammarRooms/${gbCode}/meta`),{stage:'question',index:0,deadline:Date.now()+GB_TIME,runId});}
else if(action==='gbNext'){const n=Number(m.index)+1;await update(ref(db,`grammarRooms/${gbCode}/meta`),n>=qs.length?{stage:'finished',deadline:0}:{stage:'question',index:n,deadline:Date.now()+GB_TIME});}
else if(action==='gbRestart'){await remove(ref(db,`grammarRooms/${gbCode}/submissions`));await remove(ref(db,`grammarRooms/${gbCode}/reviews`));for(const p of gbPlayers())await set(ref(db,`grammarRooms/${gbCode}/slots/${p.id}/score`),0);await update(ref(db,`grammarRooms/${gbCode}/meta`),{stage:'lobby',index:0,deadline:0});}
else {const yes=action.startsWith('gbYes_'),playerUid=action.slice(yes?6:5),ans=gbRoom.submissions?.[m.index]?.[playerUid];if(!ans||gbRoom.reviews?.[m.index]?.[playerUid])return;await set(ref(db,`grammarRooms/${gbCode}/reviews/${m.index}/${playerUid}`),{correct:yes,at:Date.now()});const p=gbPlayers().find(x=>x.uid===playerUid);if(p){if(yes)await runTransaction(ref(db,`grammarRooms/${gbCode}/slots/${p.id}/score`),x=>(Number(x)||0)+10);await saveGrammarProgress(p,Number(m.station)||0,Number(m.index)||0,yes,m.runId||`${gbCode}-${m.createdAt||0}`,qs.length);}}}catch(e){msg('Grammatik-Aktion fehlgeschlagen: '+e.message,true);}finally{gbBusy=false;}}

// Writing-Battle: children submit short original texts; the referee reviews them.
const WB_TIME=90000;
let wbCode='',wbRoom=null,wbOff=null,wbRole='',wbSlot='',wbBusy=false,wbTimer=null,wbDraft='',wbDraftIndex=-1;
function wbStop(){if(wbOff){wbOff();wbOff=null;}if(wbTimer){clearInterval(wbTimer);wbTimer=null;}wbRoom=null;wbCode='';wbRole='';wbSlot='';}
function wbListen(){if(wbOff)wbOff();wbOff=onValue(ref(db,`grammarRooms/${wbCode}`),s=>{wbRoom=s.val();if(!wbRoom){msg('Writing-Raum nicht gefunden.',true);return;}wbRender();},e=>msg('Writing-Battle: '+e.message,true));}
function wbPlayers(){return Object.entries(wbRoom?.slots||{}).map(([id,v])=>({id,...v})).sort((a,b)=>(b.score||0)-(a.score||0));}
function wbRank(){return wbPlayers().map((p,i)=>`<div class="player row"><span>${i+1}. ${esc(p.name)}</span><strong>${p.score||0} P</strong></div>`).join('')||'<p>Warte auf die Kinder.</p>';}
function writingBattleChoose(){if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}app.innerHTML=card(`<h2>✍️ Writing-Battle</h2><p>Die Kinder schreiben eigene Antworten. Du liest sie, bewertest sie und startest jede nächste Aufgabe. Pro Aufgabe gibt es bis zu 90 Sekunden.</p><p>Die sechs Aufgaben üben Adjektive/Adverbien, Simple Past und den kurzen Artikel.</p>${btn('Writing-Raum erstellen','wbCreate')}`)+card(btn('Zurück','home','alt'));}
async function wbCreate(){if(!adminLoggedIn||uid!==ADMIN_UID){loginForm();return;}wbStop();wbCode=String(Math.floor(100000+Math.random()*900000));wbRole='host';try{await set(ref(db,`grammarRooms/${wbCode}/meta`),{hostUid:uid,kind:'writing',stage:'lobby',index:0,deadline:0,createdAt:Date.now()});wbListen();}catch(e){msg('Writing-Raum konnte nicht erstellt werden: '+e.message,true);}}
function wbRender(){
 const m=wbRoom?.meta||{},i=Number(m.index||0),q=WRITING_BATTLE[i];
 if(wbRole==='player'){
  if(wbDraftIndex!==i){wbDraft='';wbDraftIndex=i;}else{const currentDraft=document.querySelector('[data-wbtext]')?.value;if(currentDraft!==undefined)wbDraft=currentDraft;}
  const submitted=wbRoom.submissions?.[i]?.[uid],review=wbRoom.reviews?.[i]?.[uid];let body='';
  if(m.stage==='lobby')body='<h3>Warteraum</h3><p>Du bist dabei. Warte, bis der Schiedsrichter startet.</p>';
  else if(m.stage==='question'&&q){
   body=`<h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><p id="wb-clock"></p>`;
   if(submitted){body+='<p class="good">✅ Antwort abgeschickt. Warte auf die nächste Aufgabe.</p>';if(review)body+=`<p>${review.correct?'✅ Richtig – 10 Punkte':'Noch nicht ganz – diesmal keine Punkte'}</p>`;body+=`<div class="player"><strong>Deine Antwort</strong><p style="white-space:pre-wrap">${esc(submitted.text)}</p></div>`;}
   else body+='<label>Deine Antwort<textarea data-wbtext rows="5" maxlength="1000" placeholder="Schreibe deinen englischen Satz oder Text hier …" style="width:100%;padding:12px;border-radius:10px;font:inherit">'+esc(wbDraft)+'</textarea></label><p class="muted">Prüfe Satzanfang, Zeitform und Adjektive/Adverbien, bevor du abschickst.</p>'+btn('Antwort abschicken','wbSubmit');
  }else if(m.stage==='finished')body='<h3>🏁 Das Battle ist beendet</h3><p>Danke fürs Schreiben!</p>'+wbRank();
  else body='<p>Die Aufgabe ist beendet. Warte auf den Schiedsrichter.</p>';
  app.innerHTML=card(`<h2>✍️ Writing-Battle · ${esc(wbRoom.slots?.[wbSlot]?.name||'')}</h2><p>Raumcode: <strong>${esc(wbCode)}</strong></p>${body}`)+card(btn('Zur Startseite','home','alt'));
  if(wbTimer)clearInterval(wbTimer);if(m.stage==='question')wbTimer=setInterval(wbClock,1000);wbClock();return;
 }
 const stage=m.stage;let out=card(`<h2>✍️ Writing-Battle · Unit 2</h2><p>Raumcode</p><div class="big">${esc(wbCode)}</div><p>${stage==='finished'?'Beendet':`Aufgabe ${Math.min(WRITING_BATTLE.length,i+1)} von ${WRITING_BATTLE.length}`}</p>${wbRank()}`);
 if(stage==='lobby')out+=card('<h3>Warteraum</h3><p>Die Kinder treten über „Spiel beitreten“ und den Raumcode bei.</p>'+btn('▶️ Battle starten','wbStart'));
 if(stage==='question'&&q){const submissions=wbRoom.submissions?.[i]||{},reviews=wbRoom.reviews?.[i]||{};out+=card(`<h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><p id="wb-host-clock"></p><p><strong>Beispielantwort:</strong> ${esc(q.sample)}</p><p class="muted">Bewerte die passende Antwort mit ✅ Richtig. Andere englische Formulierungen können ebenfalls richtig sein.</p>`+wbPlayers().map(p=>{const ans=submissions[p.uid],r=reviews[p.uid];return `<div class="player"><strong>${esc(p.name)}</strong><p style="white-space:pre-wrap">${ans?esc(ans.text):'Noch keine Antwort'}</p>${r?`<p>${r.correct?'✅ Richtig – bewertet':'❌ Noch nicht ganz – bewertet'}</p>`:ans?`${btn('✅ Richtig',`wbYes_${p.uid}`)} ${btn('❌ Noch nicht ganz',`wbNo_${p.uid}`,'alt')}`:''}</div>`;}).join('')+btn('Nächste Aufgabe ➜','wbNext'));}
 if(stage==='finished')out+=card('<h2>🏆 Endstand</h2>'+wbRank()+btn('Neues Spiel','wbRestart'));
 app.innerHTML=out+card(btn('Zur Startseite','home','alt'));if(wbTimer)clearInterval(wbTimer);if(stage==='question')wbTimer=setInterval(wbClock,1000);wbClock();
}
function wbClock(){const m=wbRoom?.meta;if(m?.stage!=='question')return;const text='⏱️ '+Math.max(0,Math.ceil((Number(m.deadline||0)-Date.now())/1000))+' Sekunden';for(const id of ['wb-clock','wb-host-clock']){const e=document.getElementById(id);if(e)e.textContent=text;}}
async function wbSubmit(){if(wbRole!=='player'||wbRoom?.meta?.stage!=='question'||wbRoom.submissions?.[wbRoom.meta.index]?.[uid])return;const text=document.querySelector('[data-wbtext]')?.value.trim();if(!text){msg('Schreibe zuerst deine Antwort.',true);return;}if(Date.now()>Number(wbRoom.meta.deadline||0)){msg('Die Schreibzeit ist abgelaufen.',true);return;}try{await set(ref(db,`grammarRooms/${wbCode}/submissions/${wbRoom.meta.index}/${uid}`),{text,at:Date.now()});wbDraft='';}catch(e){msg('Antwort konnte nicht abgeschickt werden: '+e.message,true);}}
async function saveWritingBattleProgress(p,index,correct,runId){if(!p?.uid||!p?.name)return;await runTransaction(ref(db,`soloProgress/${p.uid}/${p.name}/writingBattleUnit2`),old=>{const s=old?.runId===runId?{...old}:{runId,done:0,total:WRITING_BATTLE.length,score:0,mistakes:0};s.done=Math.min(WRITING_BATTLE.length,(Number(s.done)||0)+1);if(correct)s.score=(Number(s.score)||0)+10;else s.mistakes=(Number(s.mistakes)||0)+1;s.total=WRITING_BATTLE.length;s.finished=s.done>=WRITING_BATTLE.length;s.updatedAt=Date.now();s.timestamp=s.updatedAt;return s;});}
async function wbHost(action){if(!adminLoggedIn||uid!==ADMIN_UID||wbRole!=='host'||wbRoom?.meta?.hostUid!==uid||wbBusy)return;wbBusy=true;try{const m=wbRoom.meta,i=Number(m.index||0);if(action==='wbStart'){if(!wbPlayers().length){msg('Mindestens ein Kind muss beitreten.',true);return;}const runId=`writing-${Date.now()}`;await update(ref(db,`grammarRooms/${wbCode}/meta`),{stage:'question',index:0,deadline:Date.now()+WB_TIME,runId});}else if(action==='wbNext'){const n=i+1;await update(ref(db,`grammarRooms/${wbCode}/meta`),n>=WRITING_BATTLE.length?{stage:'finished',deadline:0}:{stage:'question',index:n,deadline:Date.now()+WB_TIME});}else if(action==='wbRestart'){await remove(ref(db,`grammarRooms/${wbCode}/submissions`));await remove(ref(db,`grammarRooms/${wbCode}/reviews`));for(const p of wbPlayers())await set(ref(db,`grammarRooms/${wbCode}/slots/${p.id}/score`),0);await update(ref(db,`grammarRooms/${wbCode}/meta`),{stage:'lobby',index:0,deadline:0});}else{const yes=action.startsWith('wbYes_'),playerUid=action.slice(yes?6:5),ans=wbRoom.submissions?.[i]?.[playerUid];if(!ans||wbRoom.reviews?.[i]?.[playerUid])return;await set(ref(db,`grammarRooms/${wbCode}/reviews/${i}/${playerUid}`),{correct:yes,at:Date.now()});const p=wbPlayers().find(x=>x.uid===playerUid);if(p){if(yes)await runTransaction(ref(db,`grammarRooms/${wbCode}/slots/${p.id}/score`),x=>(Number(x)||0)+10);await saveWritingBattleProgress(p,i,yes,m.runId||`${wbCode}-${m.createdAt||0}`);}}}catch(e){msg('Writing-Battle-Aktion fehlgeschlagen: '+e.message,true);}finally{wbBusy=false;}}

document.addEventListener('input',e=>{if(e.target?.matches('[data-wbtext]'))wbDraft=e.target.value;if(e.target?.matches('[data-writingtext]')){const s=writingLoad(),t=WRITING_TASKS[writingIndex];s.texts=s.texts||{};s.texts[t.id]=e.target.value;localStorage.setItem(writingKey(),JSON.stringify(s));if(writingSyncTimer)clearTimeout(writingSyncTimer);writingSyncTimer=setTimeout(()=>void syncWritingProgress(s),900);}else if(e.target?.matches('[data-writingplan]')){const s=writingLoad(),t=WRITING_TASKS[writingIndex];s.plans=s.plans||{};s.plans[t.id]=e.target.value;localStorage.setItem(writingKey(),JSON.stringify(s));if(writingSyncTimer)clearTimeout(writingSyncTimer);writingSyncTimer=setTimeout(()=>void syncWritingProgress(s),900);}});
document.addEventListener('change',e=>{if(e.target?.id==='subject-choice')updateBattleChoices();if(e.target?.id==='live-child-filter-main'||e.target?.id==='live-child-filter-english'||e.target?.id==='live-child-filter-math'){liveChildFilter=e.target.value;localStorage.setItem('vb_live_child_filter',liveChildFilter);renderDashboard(liveDashboardData.english,liveDashboardData.math,liveDashboardData.activity);}if(e.target?.hasAttribute('data-writingcheck')){const s=writingLoad(),t=WRITING_TASKS[writingIndex];s.checks=s.checks||{};s.checks[t.id]=s.checks[t.id]||[];s.checks[t.id][Number(e.target.dataset.writingcheck)]=e.target.checked;localStorage.setItem(writingKey(),JSON.stringify(s));if(writingSyncTimer)clearTimeout(writingSyncTimer);writingSyncTimer=setTimeout(()=>void syncWritingProgress(s),900);}});
document.addEventListener('click',e=>{const ga=e.target.closest('[data-action]')?.dataset.action;if(ga==='mathExamChoose'){mathExamChoose();return;}if(ga==='mathExamCreate'){void mathExamCreate();return;}if(ga==='fractionBattleChoose'){fractionBattleChoose();return;}if(ga==='fractionBattleCreate'){void fractionBattleCreate();return;}if(ga==='cbChoose'){cbChoose();return;}if(ga==='cbCreate'){void cbCreate();return;}if(ga==='listenBattleChoose'){listeningBattleChoose();return;}if(ga==='listeningBattleCreate'){void listeningBattleCreate();return;}if(ga==='gbChoose'){gbChoose();return;}if(ga==='gbCreate'){void gbCreate();return;}if(ga==='writingBattleChoose'){writingBattleChoose();return;}if(ga==='wbCreate'){void wbCreate();return;}if(['wbStart','wbNext','wbRestart'].includes(ga)||/^wb(Yes|No)_/.test(ga||'')){void wbHost(ga);return;}if(ga==='wbSubmit'){void wbSubmit();return;}if(['gbStart','gbNext','gbRestart'].includes(ga)||/^gb(Yes|No)_/.test(ga||'')){void gbHost(ga);return;}const ma=e.target.closest('[data-mathanswer]');if(ma){mathAnswer(Number(ma.dataset.mathanswer));return;}const mathButton=e.target.closest('[data-action]');if(mathButton&&mathAction(mathButton.dataset.action))return;const a=e.target.closest('[data-action]'),ans=e.target.closest('[data-answer]'),sa=e.target.closest('[data-soloanswer]'),ra=e.target.closest('[data-readinganswer]'),ca=e.target.closest('[data-clozeanswer]'),la=e.target.closest('[data-listenanswer]');if(ans){answer(Number(ans.dataset.answer));return;}if(sa){soloAnswer(Number(sa.dataset.soloanswer));return;}if(ra){readingAnswer(Number(ra.dataset.readinganswer));return;}if(ca){clozeAnswer(Number(ca.dataset.clozeanswer));return;}if(la){listenAnswer(Number(la.dataset.listenanswer));return;}if(!a)return;const v=a.dataset.action;if(v==='home')home();else if(v==='readingBattleChoose')readingBattleChoose();else if(v==='readingBattleCreate')void readingBattleCreate();else if(v==='readingBattleEn'){readingBattleLanguage='en';if(room)render();return;}else if(v==='readingBattleDe'){readingBattleLanguage='de';if(room)render();return;}else if(v==='adminForm')loginForm();else if(v==='adminLogin')void adminLogin();else if(v==='adminLogout')void adminLogout();else if(v==='host')chooseBattle();else if(v==='mathHost')chooseBattle('math');else if(v==='createRoom')void makeRoom();else if(v==='join')joinForm();else if(v==='enter')enter();else if(['start','reset'].includes(v))hostAction(v);else if(v==='solo')soloChooseName();else if(v==='writingMenu')writingMenu();else if(v==='writingModel'){writingModelVisible=!writingModelVisible;writingRender();}else if(v==='writingComplete')writingToggleComplete();else if(/^writingOpen[0-2]$/.test(v))writingOpen(Number(v.slice(-1)));else if(v==='readingMenu')readingMenu();else if(v==='readingIntro')readingIntro();else if(v==='readingStart')readingStart();else if(v==='readingLangEn'){readingLanguage='en';readingIntroRender();}else if(v==='readingLangDe'){readingLanguage='de';readingIntroRender();}else if(v==='readingNext')readingNext();else if(v==='readingTextCheck')readingTextCheck();else if(v==='readingTextNext')readingTextNext();else if(v==='dashboard')void showDashboard();else if(v==='resetLearning')void resetLearning(a.dataset.resetSubject);else if(v==='soloChangeName')soloChooseName();else if(v==='soloMistakes')showMyMistakes();else if(v==='soloHome')soloHome();else if(/^soloName[0-3]$/.test(v))soloSetName(Number(v.slice(-1)));else if(/^soloStart[012]$/.test(v))soloStart(Number(v.slice(-1)));else if(/^soloResume[012]$/.test(v))soloResume(Number(v.slice(-1)));else if(/^clozeStart[01]$/.test(v))clozeStart(Number(v.slice(-1)));else if(/^clozeResume[01]$/.test(v))clozeResume(Number(v.slice(-1)));else if(v==='listenStart')listenStart();else if(v==='listenResume')listenResume();else if(v==='listenNext')listenNext();else if(v==='clozeNext')clozeNext();else if(v==='soloNext')soloNext();});
home();try{const fb=initializeApp(firebaseConfig),auth=getAuth(fb);authClient=auth;db=getDatabase(fb);onAuthStateChanged(auth,u=>{const wasAdmin=adminLoggedIn;uid=u?.uid||'';adminLoggedIn=!!u&&u.uid===ADMIN_UID;if(wasAdmin!==adminLoggedIn)home();if(!u)signInAnonymously(auth).catch(e=>msg('Anmeldung fehlgeschlagen: '+e.message,true));});}catch(e){msg('Firebase-Konfiguration fehlerhaft: '+e.message,true);}
